import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework._FWOmmqu.js";const u=JSON.parse('{"title":"Live Chat (developer)","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Live Chat (developer) | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/live-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Live Chat (developer) | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/live-chat"}]]},"headers":[],"relativePath":"developer-guide/live-chat.md","filePath":"developer-guide/live-chat.md","lastUpdated":1789593659000}'),c={name:"developer-guide/live-chat.md"};function d(s,e,n,r,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="live-chat-developer" tabindex="-1">Live Chat (developer) <a class="header-anchor" href="#live-chat-developer" aria-label="Permalink to &quot;Live Chat (developer)&quot;">​</a></h1><p>Free Communication module (<code>live-chat</code> <strong>1.0.1</strong>). Public widget traffic resolves the workspace by widget <code>public_key</code> (central/web routes), initializes tenancy, checks entitlement, then ends tenancy — same pattern as custom Lead webhooks.</p><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Auth</th></tr></thead><tbody><tr><td><code>GET/POST /api/public/live-chat/{publicKey}/…</code></td><td>Widget key + visitor Bearer session token (SHA-256 hashed at rest)</td></tr><tr><td><code>/api/tenant/v1/live-chat/…</code></td><td><code>auth:tenant-api</code> + <code>module:live-chat</code> + Spatie <code>can:</code></td></tr><tr><td><code>public/widgets/live-chat.js</code></td><td>Static embed script (<code>data-key</code>, <code>data-api-base</code>)</td></tr></tbody></table><p>Throttle: <code>live-chat-widget</code> (60/min by IP + key) and <code>live-chat-widget-session</code> (10/min for session create); disabled in testing. CSRF excepted for <code>api/public/live-chat/*</code>.</p><p><strong>CORS:</strong> <code>LiveChatPublicCors</code> reflects <code>Origin</code> for credential-less public widget paths only (does not open the rest of the API).</p><p><strong>Public DTOs:</strong> Visitor responses use <code>LiveChatPublicConversationResource</code> / <code>LiveChatPublicMessageResource</code> — uuid/status/body/direction/timestamps only (no assignee, Lead, visitor IP, or sender email).</p><p><strong>Sessions:</strong> Expire after 7 days from creation. Regenerating the public key (or deactivating the widget / cancelling the module) revokes all visitor session hashes. Retention: <code>live-chat:purge-visitors --days=90</code> (daily).</p><h2 id="soft-leads" tabindex="-1">Soft Leads <a class="header-anchor" href="#soft-leads" aria-label="Permalink to &quot;Soft Leads&quot;">​</a></h2><p><code>PATCH …/conversations/{id}</code> with <code>lead_id</code> calls <code>LiveChatConversationService::linkLead</code>. Requires Leads entitled; null unlinks. UI may create via existing Leads API then patch.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p><code>LiveChatInboundMessageNotification</code> (<code>live-chat.inbound</code>) → recipients with <code>live-chat.view</code> (assignee-scoped when assigned).</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Pest: <code>tests/Feature/Tenant/LiveChat/LiveChatModuleTest.php</code>. Playwright: <code>npm run test:e2e:live-chat</code>.</p><p>Production readiness: <a href="/deployment/live-chat-production-readiness">Live Chat production readiness</a>.</p>',15)])])}const v=t(c,[["render",d]]);export{u as __pageData,v as default};
